/**
 * Canonical Relay-style connection wrapper used across every
 * entity-client model for nested collections (agents, skills, fields,
 * automations, users, …). Mirrors what antman returns from its
 * GraphQL-flavored REST endpoints.
 *
 * Lives at the top of the entity-client — not inside any single
 * client's `models/` — so every client imports the same definition
 * rather than re-declaring it under a prefixed name.
 *
 * Carries `pageInfo` so agent-authored scripts can walk pages when
 * they need to. Many antman endpoints already page under the hood;
 * exposing the cursor metadata lets callers iterate without having
 * to re-derive the structure.
 */
export interface PageInfo {
    readonly startCursor?: string;
    readonly endCursor?: string;
    readonly hasNextPage?: boolean;
    readonly hasPreviousPage?: boolean;
}
export interface Edge<T> {
    readonly cursor?: string;
    readonly node: T;
}
export interface Connection<T> {
    readonly total?: number;
    readonly edges: ReadonlyArray<Edge<T>>;
    readonly pageInfo?: PageInfo;
}
